const crypto = require('crypto');

const toStringOrNull = (v) => {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  return s ? s : null;
};

const toNumber = (v) => {
  const s = toStringOrNull(v);
  if (!s) return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
};

return items.map((item) => {
  const r = item.json;

  const wbs_id = toStringOrNull(r.wbs_id ?? r.WBS_ID ?? r['WBS ID'] ?? r.id);
  const title = toStringOrNull(r.title ?? r.Title ?? r.name ?? r.Name);

  if (!wbs_id || !title) {
    return {
      json: {
        _skip: true,
        reason: 'missing_wbs_id_or_title',
        raw: {
          wbs_id: r.wbs_id ?? r.WBS_ID ?? r['WBS ID'] ?? r.id ?? null,
          title: r.title ?? r.Title ?? r.name ?? r.Name ?? null
        }
      }
    };
  }

  const normalized = {
    _skip: false,
    wbs_id,
    title,
    owner: toStringOrNull(r.owner ?? r.Owner ?? r.assignee),
    status: toStringOrNull(r.status ?? r.Status),
    start_date: toStringOrNull(r.start_date ?? r.Start ?? r.start),
    end_date: toStringOrNull(r.end_date ?? r.End ?? r.end),
    estimate_h: toNumber(r.estimate_h ?? r.estimate ?? r.Estimate),
    actual_h: toNumber(r.actual_h ?? r.actual ?? r.Actual),
    priority: toStringOrNull(r.priority ?? r.Priority),
    parent_wbs_id: toStringOrNull(r.parent_wbs_id ?? r.parent_id ?? r.Parent),
    milestone: toStringOrNull(r.milestone ?? r.Milestone),
    url: toStringOrNull(r.url ?? r.URL ?? r.link),
    source_updated_at: toStringOrNull(r.updated_at ?? r.source_updated_at)
  };

  // Hash normalized payload (excluding row_hash itself)
  const { _skip, ...payloadObj } = normalized;
  const payload = JSON.stringify(payloadObj);
  const hash = crypto.createHash('sha256').update(payload).digest('hex');

  return { json: { ...normalized, row_hash: `sha256:${hash}` } };
});

const pad2 = (n) => String(n).padStart(2, '0');
const now = new Date();
const ts = `${now.getFullYear()}${pad2(now.getMonth() + 1)}${pad2(now.getDate())}_${pad2(now.getHours())}${pad2(now.getMinutes())}${pad2(now.getSeconds())}`;

// NOTE: Avoid using $env.* here. Some n8n setups block env access in nodes.
const cfgItem = ($items('Config', 0, 0)[0] || { json: {} }).json;
const spreadsheetId = cfgItem.wbs_sheet_id || null;
const sheetName = cfgItem.wbs_sheet_name || 'WBS';
const range = cfgItem.wbs_sheet_range || 'A:Z';

const all = $input.all().map((i) => i.json);
const tasks = all
  .filter((r) => !r._skip)
  .map((r) => {
    const { _skip, ...t } = r;
    return t;
  });
const errors = all
  .filter((r) => r._skip)
  .map((r) => {
    const { _skip, ...e } = r;
    return e;
  });

return [
  {
    json: {
      fileName: `wbs_${ts}.json`,
      content: {
        generated_at: now.toISOString(),
        source: {
          type: 'google_sheets',
          spreadsheet_id: spreadsheetId,
          sheet_name: sheetName,
          range
        },
        count: tasks.length,
        error_count: errors.length,
        tasks,
        errors
      }
    }
  }
];
